const { createNotifierFromStrategy } = require('./core');
const email = require('./channels/email');
const sms = require('./channels/sms');
const slack = require('./channels/slack');
const inapp = require('./channels/inapp');

const strategies = { email, sms, slack, inapp };

const registry = Object.keys(strategies).reduce((all, channel) => {
  all[channel] = (options = {}) => createNotifierFromStrategy(strategies[channel], options);
  return all;
}, {});

function createNotifier(channel, options = {}) {
  const factory = Object.prototype.hasOwnProperty.call(registry, channel) ? registry[channel] : null;
  if (!factory) {
    throw new TypeError(`unknown notification channel: ${channel}`);
  }
  return factory(options);
}

function createAllNotifiers(options = {}) {
  return Object.keys(registry).reduce((all, channel) => {
    all[channel] = createNotifier(channel, options);
    return all;
  }, {});
}

module.exports = {
  createNotifier,
  createAllNotifiers,
  registry
};
